"use client"

import type { ComponentProps } from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"
import {
  composeRenderProps,
  SelectionIndicator,
  TabList as TabListPrimitive,
  TabPanel as TabPanelPrimitive,
  Tab as TabPrimitive,
  Tabs as TabsPrimitive
} from "react-aria-components"

function Tabs({ className, ...props }: ComponentProps<typeof TabsPrimitive>) {
  return (
    <TabsPrimitive
      className={cn("cn-tabs group/tabs flex data-[orientation=horizontal]:flex-col", className)}
      data-slot="tabs"
      {...props}
    />
  )
}

const tabsListVariants = cva(
  "cn-tabs-list group/tabs-list [&::-webkit-scrollbar]:hidden flex w-fit items-center justify-center text-muted-foreground group-data-[orientation=vertical]/tabs:h-fit group-data-[orientation=vertical]/tabs:flex-col",
  {
    variants: {
      variant: {
        default: "cn-tabs-list-variant-default bg-muted",
        line: "cn-tabs-list-variant-line gap-1 bg-transparent"
      }
    },
    defaultVariants: {
      variant: "default"
    }
  }
)

function TabsList({
  className,
  variant = "default",
  ...props
}: ComponentProps<typeof TabListPrimitive> & VariantProps<typeof tabsListVariants>) {
  return (
    <TabListPrimitive
      className={cn(tabsListVariants({ variant }), className)}
      data-slot="tabs-list"
      data-variant={variant}
      {...props}
    />
  )
}

function TabsTrigger({ className, children, ...props }: ComponentProps<typeof TabPrimitive>) {
  return (
    <TabPrimitive
      className={composeRenderProps(className, (className) =>
        cn(
          "cn-tabs-trigger group/tab relative isolate inline-flex h-[calc(100%-1px)] flex-1 cursor-default items-center justify-center whitespace-nowrap text-foreground/60 transition-all hover:text-foreground focus-visible:border-ring focus-visible:outline-1 focus-visible:outline-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 data-disabled:pointer-events-none data-selected:text-foreground data-disabled:opacity-50 group-data-[orientation=vertical]/tabs:w-full group-data-[orientation=vertical]/tabs:justify-start dark:text-muted-foreground dark:data-selected:text-foreground dark:hover:text-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0",
          className
        )
      )}
      data-slot="tabs-trigger"
      {...props}
    >
      {composeRenderProps(children, (children) => (
        <>
          {children}
          <SelectionIndicator
            className={cn(
              "cn-tabs-trigger-aria absolute top-0 left-0 -z-1 size-full rounded-[inherit] motion-safe:transition-[translate,width,color,height]",
              "group-data-[variant=line]/tabs-list:bg-transparent dark:group-data-[variant=line]/tabs-list:border-transparent dark:group-data-[variant=line]/tabs-list:bg-transparent",
              "bg-background dark:border-input dark:bg-input/30",
              "after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-[orientation=horizontal]/tabs:after:inset-x-0 group-data-[orientation=vertical]/tabs:after:inset-y-0 group-data-[orientation=vertical]/tabs:after:-right-1 group-data-[orientation=horizontal]/tabs:after:bottom-[-5px] group-data-[orientation=horizontal]/tabs:after:h-0.5 group-data-[orientation=vertical]/tabs:after:w-0.5 group-data-[variant=line]/tabs-list:after:opacity-100"
            )}
            data-slot="selected-indicator"
          />
        </>
      ))}
    </TabPrimitive>
  )
}

function TabsContent({ className, ...props }: ComponentProps<typeof TabPanelPrimitive>) {
  return (
    <TabPanelPrimitive
      className={cn("cn-tabs-content flex-1 outline-none", className)}
      data-slot="tabs-content"
      {...props}
    />
  )
}

Tabs.Content = TabsContent
Tabs.List = TabsList
Tabs.Trigger = TabsTrigger

export { Tabs, TabsContent, TabsList, TabsTrigger, tabsListVariants }
